+            assert!(PDRouter::resolve_ctx_url_target(&[worker.clone()], Some(&headers)).is_err());
+        }
+        let mut headers = HeaderMap::new();
+        headers.insert("x-smg-target-worker", "http://ctx-a@0".parse().unwrap());
+        assert!(PDRouter::resolve_ctx_url_target(
